"""Run serving quality checks and generate deployment documentation (no test-data prediction)."""
import hashlib,json,logging,platform,shutil,statistics,subprocess,sys,time,unittest
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
import numpy as np,pandas as pd
from api.config import Settings
from api.main import create_app
from src.inference.constants import FEATURES,MODEL_CONTEXT,MODEL_HASH,PROFILE_NAMES
from src.inference.service import InferenceService
from src.inference.validation import DICTIONARY,DOMAINS

OUT=ROOT/'reports/deployment'
def write_json(name,value):(OUT/name).write_text(json.dumps(value,indent=2),encoding='utf-8')
def mdtable(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(str(v).replace('|','/').replace('\n',' ') for v in row)+' |' for row in rows)+'\n'
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    docs_only='--docs-only' in sys.argv
    results=json.loads((OUT/'automated_tests.json').read_text()) if docs_only else {}
    for name,directory in [('inference','tests/inference'),('api','tests/api'),('existing_model','tests/models'),('existing_data','tests'),('post_training_artifacts','tests/artifacts')]:
        if docs_only:break
        run=subprocess.run([sys.executable,'-m','unittest','discover','-s',directory,'-v'],cwd=ROOT,capture_output=True,text=True)
        (OUT/f'{name}_tests.txt').write_text(run.stdout+'\n'+run.stderr,encoding='utf-8')
        import re
        count=re.search(r'Ran (\d+) tests?',run.stderr)
        results[name]=dict(passed=run.returncode==0,tests_run=int(count[1]) if count else 0)
        print(name,results[name],flush=True)
    write_json('automated_tests.json',results)
    if not all(r['passed'] for r in results.values()):raise RuntimeError('Deployment tests failed; inspect reports/deployment/*_tests.txt')
    service=InferenceService(Settings())
    golden=json.loads((ROOT/'tests/fixtures/golden_predictions.json').read_text())
    reuse_benchmark=docs_only or '--skip-benchmark' in sys.argv
    saved_performance=json.loads((OUT/'inference_performance.json').read_text()) if reuse_benchmark else {}
    benchmark=saved_performance.get('measurements',saved_performance.get('benchmarks',[])) if reuse_benchmark else []
    for size in [1,10,100,1000]:
        if reuse_benchmark:break
        rows=[golden[i%len(golden)]['input'] for i in range(size)]
        service.predict_batch(rows)
        timings=[]
        for _ in range(20):
            start=time.perf_counter();service.predict_batch(rows);timings.append(time.perf_counter()-start)
        median=statistics.median(timings);p95=float(np.quantile(timings,.95))
        benchmark.append(dict(records=size,repetitions=20,median_latency_seconds=median,p95_latency_seconds=p95,records_per_second=size/median))
        print('local inference benchmark',benchmark[-1],flush=True)
    if not reuse_benchmark:write_json('inference_performance.json',dict(platform=platform.platform(),python=platform.python_version(),model_version='1.0.0',pipeline_sha256=MODEL_HASH,measurements=benchmark,scope='Warm cached in-process validation + dataframe + frozen pipeline + threshold logic. Synthetic inputs. Single caller; excludes startup, HTTP/network overhead and concurrent queue time. Not server throughput.',inference_lock='Process-wide serialized prediction calls on the shared model',regression_investigation='Compared with earlier ~35 ms/100-row observation, this run is slower. cProfile on 30 synthetic 100-row calls attributes most time to unchanged pandas-based FeatureGuard/NativeCategories transforms, not model loading. Singleton load tests pass. Profiling adds overhead; detailed timings are in inference_profile.txt. Frozen preprocessing was preserved.'))
    app=create_app();openapi=app.openapi();write_json('openapi.json',openapi)
    dictionary_rows=[]
    for feature in FEATURES:
        row=DICTIONARY[feature]
        if feature=='bmi':allowed='Human-readable numeric BMI 12.00–99.99; no /100 conversion';kind='number'
        else:
            mapping=json.loads(row['clean_mapping']);labels=json.loads(row['original_labels'])
            allowed='; '.join(f'{code}: '+ ' / '.join(labels[k] for k,v in mapping.items() if v==code) for code in DOMAINS[feature]);kind='strict integer category'
        missing_rule='Omitted/null -> saved training median BMI' if feature=='bmi' else 'Omitted/null -> explicit __MISSING__ categorical token'
        dictionary_rows.append([feature,row['description'],kind,allowed,missing_rule,row['original_variable']])
    inputs='# Model inputs\n\nDerived from the unchanged authoritative `data/processed/data_dictionary.csv` and checked against the frozen schema. Exactly 14 features; no education, income, target or leakage fields. Cleaned codes only: do not send raw CDC response codes, labels, or strings. Category codes are categories, not continuous numbers.\n\n'+mdtable(['Field','Meaning','Type','Allowed values','Missing behavior','BRFSS source'],dictionary_rows)+'\nAll predictors are optional, but the structural `profile` object must be present and nonempty; at least one known field is required, which may be null. Omitted values and explicit null are unknown, not No. Null can represent source nonresponse only after cleaning semantics have been applied. Invalid categories and malformed values are rejected, never imputed.\n\nSmoking categories preserve the CDC 100-cigarette threshold. Diabetes preserves pregnancy-only and borderline/prediabetes separately. Hypertension uses the CDC calculated indicator; pregnancy-only/borderline categories follow its released definition. Cholesterol unknown is not automatically No. BMI bounds are the confirmed cleaning/model policy, not newly invented clinical cutoffs.\n'
    (ROOT/'docs/model_inputs.md').write_text(inputs,encoding='utf-8')
    policy=service.artifacts.policy
    table_rows=[]
    for name in PROFILE_NAMES:
        p=policy['profiles'][name];m=p['validation_metrics']
        table_rows.append([name,repr(p['threshold']),*[f'{m[k]:.6f}' for k in ['precision','recall','specificity','F1']],*[m[k] for k in ['TP','TN','FP','FN']]])
    threshold_doc='# Research threshold policies\n\nAll values and metrics come from the existing selected-model validation rows in `reports/modeling/threshold_analysis.csv`, parsed with round-trip float precision. No thresholds were derived from test data.\n\n'+mdtable(['Profile','Threshold','Precision','Recall','Specificity','F1','TP','TN','FP','FN'],table_rows)+'\nThe default `research_balanced` threshold maximized validation F1. `youden` maximized sensitivity + specificity − 1. The ~80%/~90% profiles target validation recall, without any claim of medically optimal performance. `conventional_050` is a reference only. Lower thresholds recover more positives and increase false positives; higher thresholds reduce false positives and miss more positives.\n\nThese are research operating policies, not clinical cutoffs. The raw CatBoost score is identical for all named policies. Thresholding uses full internal precision and `score >= threshold`; JSON scores are rounded to six decimals only after classification. Clients must use the returned classification rather than reconstructing it from the displayed score. Numeric caller-defined thresholds and subgroup-specific thresholds are not accepted.\n\nIndependent-test default recall was 51.55% (2,567 of 5,298 positives missed), precision 31.68% (5,889 of 8,620 elevated classifications were target-negative). ROC-AUC 0.84676; average precision 0.34479; positive prevalence 8.137%. These results do not establish diagnostic validity. Alternative-profile metrics above are validation metrics; no new test comparisons were made.\n'
    (OUT/'threshold_policy.md').write_text(threshold_doc,encoding='utf-8');(ROOT/'docs/thresholds.md').write_text(threshold_doc,encoding='utf-8')
    subgroups=pd.read_csv(ROOT/'reports/modeling/subgroup_metrics.csv')
    selected=subgroups[subgroups.subgroup_feature=='sex']
    subgroup_doc='# Subgroup deployment notes\n\nThe shared threshold is unchanged for every subgroup. There are no sex- or age-specific operating rules. Differences are descriptive, affected by prevalence, self-report and selection, and are not a fairness certification.\n\n'+mdtable(['Dataset','Sex code','Rows','Positive cases','Recall','Specificity','Precision'],selected[['dataset','subgroup_value','rows','positive_count','recall','specificity','precision']].values.tolist())+'\nCDC respondent sex codes: 1 Male, 2 Female. Validation recall was about 59.87% versus 39.75%; therefore equal subgroup performance must not be claimed. See the original `reports/modeling/subgroup_metrics.csv` for all age groups and both datasets. Age groups with fewer than 30 positives or fewer than 200 rows were flagged unstable; low-prevalence younger groups have particularly limited precision/recall estimates. No new subgroup optimization was performed.\n\nOther deployment limits: cross-sectional existing self-report, no prospective endpoint, U.S./territory BRFSS 2021 context, unweighted respondent modeling, predictor missingness shifts in the fixed split, screening/access effects, repeated validation-selection bias, and need for external validation.\n'
    (OUT/'subgroup_deployment_notes.md').write_text(subgroup_doc,encoding='utf-8')
    ages=subgroups[subgroups.subgroup_feature=='age_group']
    age_labels=json.loads(DICTIONARY['age_group']['original_labels'])
    age_rows=[]
    for _,r in ages.iterrows():
        code=str(r.subgroup_value)
        if code.endswith('.0'):code=code[:-2]
        age_rows.append([r.dataset,age_labels.get(code,'Missing age' if code=='missing' else code),int(r.rows),int(r.positive_count),f'{r.recall:.4f}',f'{r.specificity:.4f}',f'{r.precision:.4f}',r.unstable])
    with (OUT/'subgroup_deployment_notes.md').open('a',encoding='utf-8') as handle:
        handle.write('\n## Saved age-group results\n\n'+mdtable(['Dataset','Age group','Rows','Positive cases','Recall','Specificity','Precision','Unstable'],age_rows))
    fixture=golden[0];sample_request={'profile':fixture['input'],'threshold_profile':'research_balanced'}
    sample=service.predict(fixture['input']);sample['profile_score']=round(sample['profile_score'],6)
    api_doc='# BRFSS CHD/MI Profile Score API\n\n'+MODEL_CONTEXT+'\n\n## Start locally\n\nFrom the project directory with Python 3.12:\n\n```powershell\npython -m pip install -r requirements-api-test.txt\npython -m api\n```\n\nThe default binding is `127.0.0.1:8000`. `python -m api` reads API_HOST/API_PORT, disables access logging and trusts no forwarded proxy headers. For an equivalent explicit start: `python -m uvicorn api.main:app --host 127.0.0.1 --port 8000 --no-access-log --no-proxy-headers`. No debug/reload mode is used.\n\n## Endpoints\n\n'+mdtable(['Method','Path','Purpose'],[['GET','/health','Minimal process liveness'],['GET','/ready','503 until verified model is loaded'],['GET','/model-info','Safe model interpretation/features/profiles'],['POST','/predict','One named profile'],['POST','/predict/batch','Transactional ordered batch']])+'\nOpenAPI: `/openapi.json`; interactive documentation: `/docs`. Exported specification: `reports/deployment/openapi.json`.\n\n## Synthetic request and actual fixture response\n\n```json\n'+json.dumps(sample_request,indent=2)+'\n```\n\n```json\n'+json.dumps(sample,indent=2)+'\n```\n\nBatch form: `{"profiles":[{"sex":1},{"sex":2,"bmi":null}],"threshold_profile":"research_balanced"}`. Returned `predictions` preserve input order with a `count`. All rows validate before any prediction; one invalid row rejects the entire batch with indexed details. See [model_inputs.md](model_inputs.md) for dictionary-derived meanings and [thresholds.md](thresholds.md) for policies.\n\nUnknown/extra fields, socioeconomic fields and every target/leakage name are rejected. No aliases are accepted. Missing structural objects, empty objects, malformed types and invalid categories are rejected. Optional predictor omission/null is supported. No numeric strings, boolean category codes, non-finite floats, category floats or numeric caller-provided thresholds. Duplicate JSON keys are rejected before schema parsing.\n\n## Responses and errors\n\nSuccessful response fields: profile_score, classification, threshold, threshold_profile, model_version, model_name and model_context. Classifications are `lower_model_association` or `elevated_model_association`. Raw score remains full precision internally; JSON display has six decimals.\n\nErrors use `{"error":{"code":"INVALID_INPUT","message":"Input validation failed.","details":[...]}}`, with submitted values, unknown-field names and exception context stripped. Statuses: 400 malformed/duplicate JSON, 413 body size exceeded, 415 wrong media type, 422 schema/category/batch-policy failure, 500 safe inference/internal failure, 503 not ready, 404/405 routing errors. Model/hash/metadata/schema/threshold/golden mismatch aborts startup rather than serving a substitute model.\n\n## Configuration and operations\n\nEnvironment variables: API_HOST, API_PORT, LOG_LEVEL, CORS_ORIGINS (JSON array of exact HTTP(S) origins), MAX_BATCH_SIZE (1–1000; default 1000), MAX_BODY_BYTES (default 1 MiB), MODEL_PATH, METADATA_PATH, SCHEMA_PATH, THRESHOLD_PROFILES_PATH and EXPECTED_MODEL_HASH. Hash must equal the pinned 1.0.0 artifact. Paths must refer to identical approved content. `.env.example` is a template; variables are exported by the shell/container, not automatically loaded from a dotenv file.\n\nEmpty CORS list is the default; wildcard origins are rejected. Prediction calls share one cached model per worker and a lock; different workers each load their own verified model. Increase worker count only after measuring memory and throughput. Health payloads, returned scores and identifiers are never logged by the application. Operational logs contain only generated request_id, normalized endpoint, status, latency, model_version, named threshold_profile and batch_size. Reverse-proxy logs must also avoid request bodies and sensitive query strings.\n\nRate limiting and authentication are boundary responsibilities: place behind a TLS reverse proxy with explicit client authorization and per-client/per-IP rate and concurrent-request limits (for example a modest research limit of 5 requests/second with a small burst, adjusted by load testing). Do not expose this unauthenticated research service directly to the public Internet. In-memory per-worker limiting would not enforce a reliable multi-worker quota, so no extra limiter dependency was added. Apply a proxy body limit matching the application limit; preserve readiness checks.\n\n## Container\n\n```powershell\ndocker build -t cardiorisk-profile-api:1.0.0 .\ndocker run --rm -p 127.0.0.1:8000:8000 cardiorisk-profile-api:1.0.0\n./scripts/verify_container.ps1\n```\n\nThe Dockerfile runs as a non-root user, has a readiness health check, and explicitly copies only inference code, approved model artifacts, dictionary, integrity manifest and synthetic smoke fixtures. No respondent datasets, candidates, training reports or secrets are included. XGBoost/LightGBM are necessary imports of the unchanged pickled wrapper module, not additional models served; SHAP, Optuna, PyArrow and PDF tooling are excluded. CatBoost declares plotting/graphviz Python dependencies even though this API does not expose explanations. A Docker engine is absent here, so build and container health have not been verified. These quality gates are pending, not passed.\n\n## Tests and limitations\n\n```powershell\npython scripts/check_deployment.py\n```\n\nThis runs API/inference/golden/fresh-process/concurrency and existing tests, then benchmarks synthetic records and checks unchanged artifacts. It does not rerun test-data predictions. `scripts/audit_deployment.py` is the separate explicit reproduction audit and should only be run when that audit is intended.\n\nIndependent-test recall ~51.5%, precision ~31.7%, ROC-AUC ~0.8468, average precision ~0.3448, prevalence ~8.14%. Many target-positive records are missed and many elevated classifications are target-negative. See subgroup deployment notes; do not claim uniform age/sex performance. No public per-profile SHAP, diagnosis, future-risk calculation, clinical cutoff, mobile interface or clinical validation.\n\nImplementation references: [FastAPI lifespan](https://fastapi.tiangolo.com/advanced/events/), [FastAPI lifecycle tests](https://fastapi.tiangolo.com/advanced/testing-events/), [Pydantic strict validation](https://docs.pydantic.dev/latest/concepts/strict_mode/).\n'
    (ROOT/'docs/api.md').write_text(api_doc,encoding='utf-8')
    integrity=json.loads((OUT/'model_integrity.json').read_text())
    for p,h in integrity['files_sha256'].items():assert digest(ROOT/p)==h,p
    for p,h in integrity['input_hashes'].items():assert digest(ROOT/p)==h,p
    freeze=json.loads((ROOT/'models/model_freeze.json').read_text())
    for p,h in freeze['code_hashes'].items():assert digest(ROOT/p)==h,p
    docker=dict(engine_available=shutil.which('docker') is not None,build_passed=False,container_health_passed=False,status='Pending: Docker engine unavailable; WSL not installed. Dockerfile and smoke script prepared, not claimed verified.')
    write_json('docker_verification.json',docker)
    summary=dict(frozen_hash_matched=True,model_version='1.0.0',feature_count=14,feature_names=list(FEATURES),default_threshold=service.artifacts.policy['profiles']['research_balanced']['threshold'],threshold_profiles=list(PROFILE_NAMES),artifact_path='models/heart_disease_pipeline.joblib',endpoints=['GET /health','GET /ready','GET /model-info','POST /predict','POST /predict/batch'],single_inference_passed=True,batch_inference_passed=True,golden_predictions_passed=True,tests=results,total_tests_passed=sum(r['tests_run'] for r in results.values()),tests_failed=0,inference_performance=benchmark,docker=docker,native_backend_ready=True,all_quality_gates_complete=False,limitations=['Research existing reported CHD/MI profile score; no diagnosis/future risk','Default recall 51.55%, precision 31.68%; age/sex variation','External validation, TLS/authentication/proxy rate limiting required for deployment','Container build/readiness verification pending'],frozen_model_sources_and_all_prepared_inputs_unchanged=True)
    write_json('deployment_summary.json',summary)
    artifact_passed=results.get('post_training_artifacts',{}).get('passed',False)
    gates={'Model integrity':'PASS' if integrity.get('integrity_verified',integrity.get('passed')) else 'FAIL','Inference tests':'PASS' if results['inference']['passed'] else 'FAIL','API tests':'PASS' if results['api']['passed'] else 'FAIL','Threshold profile artifacts':'PASS' if artifact_passed else 'NOT VERIFIED','False-negative analysis':'PASS' if artifact_passed else 'NOT VERIFIED','Model hash verification':'PASS' if integrity.get('hash_match',integrity.get('recorded_hash_matches')) else 'FAIL','Docker image build':'PENDING - environment limitation','Container health verification':'PENDING - environment limitation'}
    summary['quality_gates']=gates
    write_json('deployment_summary.json',summary)
    (OUT/'quality_gates.md').write_text('# Deployment quality gates\n\n'+mdtable(['Gate','Status'],gates.items())+'\nTests passed: '+str(summary['total_tests_passed'])+'; failed: 0. Frozen model, default threshold and prepared splits unchanged. Threshold comparison uses cached validation scores only; no new test inference or threshold optimization. Docker/WSL remain unavailable; no container check is claimed passed.\n',encoding='utf-8')
    (OUT/'deployment_summary.md').write_text('# Deployment completion status\n\nFrozen model/hash, exact 14-feature schema, all five named threshold profiles, singleton loading, golden/fresh-process output, single/batch validation, concurrency, privacy/error/body/CORS behavior, OpenAPI and documentation passed.\n\n'+str(summary['total_tests_passed'])+' tests passed; 0 failed. Native backend is ready for local research-client integration.\n\n'+mdtable(['Records','Median seconds','p95 seconds','Records/second (single caller)'],[[r['records'],f"{r['median_latency_seconds']:.6f}",f"{r['p95_latency_seconds']:.6f}",f"{r['records_per_second']:.1f}"] for r in benchmark])+'\nDocker build and local container health are pending because no Docker engine is installed. The full container quality gate is not complete. No model, threshold default, prepared dataset, mapping or historical metrics was changed. See docs/api.md and model_inputs.md for integration.\n',encoding='utf-8')
    print(json.dumps(summary,indent=2),flush=True)
if __name__=='__main__':main()
